    const idx = this.pos + offset
    return idx < this.input.length ? this.input[idx] : null
  }

  advance() {
    if (this.pos >= this.input.length) return null

    const char = this.input[this.pos]
    this.pos++

    if (char === '\n') {
      this.line++
      this.column = 1
    } else if (char === '\t') {
      // Move to next multiple of 4 + 1
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }

    return char
