    // We've already seen '//'
    while (this.peek() !== null && this.peek() !== '\n') {
      this.advance()
    }
  }

  scanBlockComment() {
    // We've already seen '/*'
    let depth = 1

    while (this.peek() !== null && depth > 0) {
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }

    if (depth > 0) {
