      const char = this.peek()
      if (/[a-zA-Z0-9_]/.test(char)) {
        this.advance()
      } else {
        break
      }
    }

    const body = this.input.slice(start, this.pos)
    const kind = KEYWORDS.has(body) ? 'keyword' : 'ident'

    return new Token(this.line, startCol, kind, body)
  }

