            if (codepoint > 0x10FFFF) {
              this.error(`invalid escape \\${escaped}`)
            }
            body += String.fromCodePoint(codepoint)
            this.advance() // '}'
            break
          }
          default:
            this.error(`invalid escape \\${escaped}`)
        }
      } else {
        body += this.advance()
      }
    }

    if (this.pos > 0 && this.input[this.pos - 1] !== '"') {
      this.error('unterminated string')
    }

    return new Token(this.line, startCol, 'string', body)
  }

  scanRawString() {
    const startCol = this.column
    this.advance() // 'r'
    this.advance() // Opening quote

    let body = ''

    while (this.peek() !== null) {
      const char = this.peek()

      if (char === '"') {
        this.advance()
        break
      } else {
        body += this.advance()
      }
    }

    if (this.pos > 0 && this.input[this.pos - 1] !== '"') {
      this.error('unterminated string')
    }

    return new Token(this.line, startCol, 'rawstring', body)
  }

  scanPunctuation() {
    const startCol = this.column

    // Two-character operators (matched longest first)
    const twoCharOps = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
    for (const op of twoCharOps) {
      if (this.peek() === op[0] && this.peek(1) === op[1]) {
        this.advance()
        this.advance()
        return new Token(this.line, startCol, 'punct', op)
      }
    }

    // Single-character operators
    const singleCharOps = ['+', '-', '*', '/', '%', '=', '<', '>', '!', 
                           '(', ')', '{', '}', '[', ']', ',', ';', '.']
    const char = this.peek()
    if (singleCharOps.includes(char)) {
      this.advance()
      return new Token(this.line, startCol, 'punct', char)
    }

