      }

      if (char === '/' && this.peek(1) === '*') {
        const commentStartLine = this.line
        const commentStartCol = this.column
        this.advance()
        this.advance()
        try {
          this.scanBlockComment()
        } catch (e) {
          if (e instanceof ScanError) {
            // Re-throw with the position of the comment opening
            throw new ScanError(commentStartLine, commentStartCol, e.reason)
          }
          throw e
        }
        continue
      }

      // Identifier or keyword
      if (/[a-zA-Z_]/.test(char)) {
        this.tokens.push(this.scanIdentifier())
        continue
      }

      // Number
      if (/[0-9]/.test(char)) {
        this.tokens.push(this.scanNumber())
        continue
      }

      // String
      if (char === '"') {
        this.tokens.push(this.scanString())
        continue
      }

      // Raw string
      if (char === 'r' && this.peek(1) === '"') {
        this.tokens.push(this.scanRawString())
        continue
      }

      // Punctuation
      const punct = this.scanPunctuation()
      if (punct) {
        this.tokens.push(punct)
        continue
      }

      // Unexpected character
      this.error(`unexpected character ${char}`)
    }

    return this.tokens
  }
}
"}

