/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { Scanner, ScanError } from './scanner.js'
import { readFileSync } from 'fs'

const args = process.argv.slice(2)

// Check arguments
if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''
try {
  // Read from stdin synchronously
  const buffer = readFileSync(0, 'utf-8')
  input = buffer
} catch (e) {
  // Empty input is OK
  input = ''
}

// Scan
try {
  const scanner = new Scanner(input)
  const tokens = scanner.scan()

  if (mode === 'tokens') {
    // Output tokens
    for (const token of tokens) {
      let body = token.body
      if (token.kind === 'string' || token.kind === 'rawstring') {
        // Encode as JSON string
        body = JSON.stringify(body)
      }
      process.stdout.write(`${token.line}:${token.column} ${token.kind} ${body}\n`)
    }
  } else if (mode === 'stats') {
    // Count by kind
    const counts = {
      ident: 0,
      keyword: 0,
      number: 0,
      punct: 0,
      rawstring: 0,
      string: 0,
    }

    for (const token of tokens) {
      counts[token.kind]++
    }

    // Output in specified order
    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      process.stdout.write(`${kind} ${counts[kind]}\n`)
    }

    const total = tokens.length
    process.stdout.write(`total ${total}\n`)
  }

  process.exit(0)
} catch (e) {
  if (e instanceof ScanError) {
    process.stderr.write(`error: ${e.line}:${e.column}: ${e.reason}\n`)
    process.exit(2)
  }
  throw e
}
"}

