  // of them. Returns true when at least one digit was consumed.
  consumeDigits(ok) {
    let any = false
    let lastWasDigit = false
    for (;;) {
      const c = this.peek()
      if (ok(c)) {
        this.advance()
        any = true
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && ok(this.peek(1))) {
        this.advance()
        lastWasDigit = false
      } else {
