      else if (prefix === 'b' || prefix === 'B') ok = (c) => c === '0' || c === '1'
      else ok = (c) => c !== null && c >= '0' && c <= '7'

      const any = this.consumeDigits(ok)
      if (!any) this.numberError(start, line, column)
