          case 't': this.advance(); body += '\t'; break
          case 'r': this.advance(); body += '\r'; break
          case '\\': this.advance(); body += '\\'; break
          case '"': this.advance(); body += '"'; break
          case '0': this.advance(); body += '\0'; break
          case 'x': {
            this.advance()
            const h1 = this.peek()
            if (!isHex(h1)) bad()
            this.advance()
            const h2 = this.peek()
            if (!isHex(h2)) bad()
            this.advance()
            body += String.fromCharCode(parseInt(h1 + h2, 16))
            break
          }
          case 'u': {
            this.advance()
            if (this.peek() !== '{') bad()
            this.advance()
            let hex = ''
            while (isHex(this.peek())) hex += this.advance()
            if (hex.length === 0 || this.peek() !== '}') bad()
            const cp = parseInt(hex, 16)
            if (!(cp <= 0x10ffff)) bad()
            this.advance() // '}'
            body += String.fromCodePoint(cp)
            break
          }
          default:
            bad()
        }
        continue
      }
      body += this.advance()
    }

    return new Token(line, column, 'string', body)
  }

  scanRawString() {
    const line = this.line
    const column = this.column
    this.advance() // 'r'
    this.advance() // '"'

    let body = ''
    for (;;) {
      const c = this.peek()
      if (c === null) this.fail(line, column, 'unterminated string')
      if (c === '"') {
        this.advance()
        break
      }
      body += this.advance()
    }
    return new Token(line, column, 'rawstring', body)
  }

  scanPunctuation() {
    const line = this.line
    const column = this.column
    const a = this.peek()
    const b = this.peek(1)
    if (a !== null && b !== null && TWO_CHAR.includes(a + b)) {
      this.advance()
      this.advance()
      return new Token(line, column, 'punct', a + b)
    }
    if (a !== null && ONE_CHAR.has(a)) {
      this.advance()
      return new Token(line, column, 'punct', a)
    }
    return null
  }

  scan() {
    for (;;) {
      this.skipWhitespace()
      const char = this.peek()
      if (char === null) break

      if (char === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        this.scanLineComment()
        continue
      }

      if (char === '/' && this.peek(1) === '*') {
        const line = this.line
        const column = this.column
        this.advance()
        this.advance()
        this.scanBlockComment(line, column)
        continue
      }

      if (char === 'r' && this.peek(1) === '"') {
        this.tokens.push(this.scanRawString())
        continue
      }

      if (isIdentStart(char)) {
        this.tokens.push(this.scanIdentifier())
        continue
      }

      if (isDigit(char)) {
        this.tokens.push(this.scanNumber())
        continue
      }

      if (char === '"') {
        this.tokens.push(this.scanString())
        continue
      }

      const punct = this.scanPunctuation()
      if (punct) {
        this.tokens.push(punct)
        continue
      }

      this.fail(this.line, this.column, `unexpected character ${char}`)
    }

    return this.tokens
  }
}
