const TWO_CHAR = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

const isDigit = (c) => c !== null && c >= '0' && c <= '9'
const isHex = (c) => c !== null && /^[0-9a-fA-F]$/.test(c)
const isIdentStart = (c) => c !== null && /^[A-Za-z_]$/.test(c)
const isIdentPart = (c) => c !== null && /^[A-Za-z0-9_]$/.test(c)

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

export class Token {
  constructor(line, column, kind, body) {
    this.line = line
    this.column = column
    this.kind = kind
    this.body = body
  }
}

export class Scanner {
  constructor(input) {
    // Iterate by code points, not UTF-16 code units.
    this.chars = Array.from(input)
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  peek(offset = 0) {
    const idx = this.pos + offset
    return idx < this.chars.length ? this.chars[idx] : null
  }

  advance() {
    if (this.pos >= this.chars.length) return null
    const char = this.chars[this.pos]
    this.pos++
    if (char === '\n') {
      this.line++
      this.column = 1
    } else if (char === '\t') {
      this.column = Math.floor((this.column - 1) / 4) * 4 + 5
    } else {
      this.column++
    }
    return char
  }

  slice(start) {
    return this.chars.slice(start, this.pos).join('')
  }

  skipWhitespace() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') this.advance()
      else break
    }
  }

  scanLineComment() {
    while (this.peek() !== null && this.peek() !== '\n') this.advance()
  }

  scanBlockComment(startLine, startColumn) {
    // '/*' already consumed
    let depth = 1
    while (depth > 0) {
      if (this.peek() === null) {
        this.fail(startLine, startColumn, 'unterminated block comment')
      }
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }
  }

