    const start = this.pos
    const line = this.line
    const column = this.column
    while (isIdentPart(this.peek())) this.advance()
    const body = this.slice(start)
    return new Token(line, column, KEYWORDS.has(body) ? 'keyword' : 'ident', body)
  }

  // Consume a run of digits (matching `ok`) where `_` may only sit between two
  // of them. Returns true when at least one digit was consumed.
  consumeDigits(ok) {
    let any = false
    let lastWasDigit = false
    for (;;) {
      const c = this.peek()
      if (ok(c)) {
        this.advance()
        any = true
        lastWasDigit = true
      } else if (c === '_' && lastWasDigit && ok(this.peek(1))) {
